alter table public.orders add column if not exists amount_paid numeric(20,2) not null default 0; alter table public.orders add column if not exists balance numeric(20,2) not null default 0; update public.orders o set amount_paid=coalesce((select sum(e.amount) from public.payment_gateway_events e where e.order_id=o.id and e.status='success'),0), balance=greatest(o.total_amount-coalesce((select sum(e.amount) from public.payment_gateway_events e where e.order_id=o.id and e.status='success'),0),0); create index if not exists orders_balance_idx on public.orders(user_id,balance,payment_status); create or replace function public.admin_approve_payment_request(_request_id uuid,_decision text,_notes text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare r public.payment_requests; caller uuid:=auth.uid(); o public.orders; new_paid numeric; new_balance numeric; begin if caller is null then raise exception 'Authentication required'; end if; if not public.user_has_permission(caller,'admin:approve_payments') then raise exception 'You do not have permission to approve payments'; end if; if lower(_decision) not in ('approved','rejected') then raise exception 'Invalid payment decision'; end if; select * into r from public.payment_requests where id=_request_id for update; if not found then raise exception 'Payment request not found'; end if; if r.status<>'pending' then raise exception 'Payment request is already processed'; end if; if lower(_decision)='approved' then select * into o from public.orders where payment_reference=r.reference for update; if o.id is null and r.related_payment_id is not null then select ord.* into o from public.orders ord join public.payments p on p.payment_reference=ord.payment_reference where p.id=r.related_payment_id limit 1 for update; end if; if o.id is not null then if r.amount<=0 or r.amount>greatest(o.total_amount-o.amount_paid,0)+1 then raise exception 'Payment amount exceeds the outstanding order balance'; end if; new_paid:=least(o.total_amount,o.amount_paid+r.amount); new_balance:=greatest(o.total_amount-new_paid,0); update public.orders set amount_paid=new_paid,balance=new_balance,payment_status=case when new_balance<=0 then 'paid' else 'pending' end,updated_at=now() where id=o.id; end if; update public.payment_requests set status='approved',processed_by=caller,processed_at=now(),admin_notes=nullif(trim(coalesce(_notes,'')),''),updated_at=now() where id=r.id; update public.estate_documentation_payments set status='paid',updated_at=now() where reference=r.reference and status='awaiting_approval'; update public.payments set status=case when balance<=0 then 'completed' else 'active' end,updated_at=now() where reference=r.reference and status='awaiting_approval'; return jsonb_build_object('success',true,'request_id',r.id,'decision','approved','order_id',o.id,'amount_paid',coalesce(o.amount_paid,0),'balance',coalesce(o.balance,0)); else update public.payment_requests set status='rejected',processed_by=caller,processed_at=now(),admin_notes=nullif(trim(coalesce(_notes,'')),''),updated_at=now() where id=r.id; update public.orders set payment_status='rejected',updated_at=now() where payment_reference=r.reference and payment_status='awaiting_approval'; update public.estate_documentation_payments set status='rejected',updated_at=now() where reference=r.reference and status='awaiting_approval'; update public.payments set status='rejected',updated_at=now() where reference=r.reference and status='awaiting_approval'; return jsonb_build_object('success',true,'request_id',r.id,'decision','rejected'); end if; end; $$; revoke all on function public.admin_approve_payment_request(uuid,text,text) from public; grant execute on function public.admin_approve_payment_request(uuid,text,text) to authenticated;
